"""Saca RunID de value['data']; si queda vacío, usa value['allRunDs']."""
data = value["data"]
out = []

# 1) Dataset directo
if data is not None and hasattr(data, "getRowCount"):
	for row in system.dataset.toPyDataSet(data):
		try:
			out.append(int(row["RunID"]))
		except:
			pass

# 2) String JSON -> decodificar
elif isinstance(data, basestring):
	try:
		data = system.util.jsonDecode(data)
	except:
		data = None

# 3) Dict/List/ArrayList Java
if isinstance(data, dict):
	data = [data]
if data is not None and not isinstance(data, (list, tuple)):
	# Soporta java.util.ArrayList u otros iterables
	try:
		data = list(data)
	except:
		data = None
if isinstance(data, (list, tuple)):
	for item in data:
		try:
			out.append(int(item.get("RunID")))
		except:
			pass

# Deduplicar preservando orden
out = list(dict.fromkeys(out))

# 4) Fallback: Dataset pre-creado en value['allRunDs']
if not out:
	ds = value["allRunDs"]
	if ds is not None and hasattr(ds, "getRowCount"):
		for row in system.dataset.toPyDataSet(ds):
			try:
				out.append(int(row["RunID"]))
			except:
				pass
		out = list(dict.fromkeys(out))

return out

